define('taoMediaManager/controller/editInstance',['jquery', 'layout/actions/binder', 'util/url', 'taoItems/preview/inlinePropertiesPreview', 'ui/previewer'], function ($, binder, urlUtil, inlinePropertiesPreview) {
  'use strict';

  var manageMediaController = {
    start() {
      var $previewer = $('.previewer');
      var mimeType = $('.main-container').data('mimeType');
      var isPassage = mimeType === 'application/qti+xml';
      var isPreviewEnabled = $previewer.data('enabled');
      if (isPreviewEnabled) {
        if (isPassage) {
          $previewer.attr('id', 'item-properties-preview');
          $previewer.closest('.data-container-wrapper').attr('id', 'item-properties-preview-column');
          inlinePropertiesPreview.init({
            isPreviewEnabled,
            itemUri: $('#edit-media').data('uri')
          });
        } else {
          var file = {};
          file.url = $previewer.data('url');
          file.mime = $previewer.data('type');
          file.containerClass = 'no-background';
          $previewer.previewer(file);
        }
      }
      if (isPassage) {
        $('#media-authoring').show();
      } else {
        $('#media-authoring').hide();
      }
      $('#edit-media').off().on('click', function () {
        var action = {
          binding: 'load',
          url: urlUtil.route('editMedia', 'MediaImport', 'taoMediaManager')
        };
        binder.exec(action, {
          classUri: this.dataset.classuri,
          id: this.dataset.uri
        } || this._resourceContext);
      });
    }
  };
  return manageMediaController;
});
